#!/usr/bin/env bash
# -----------------------------------------------------------------------
# Elle / AWDIT Verification Pipeline Wrapper
#
# Takes .edn history files generated by IsoTest's ElleLogger and runs
# them through the Clojure-based Elle checker to produce an automated
# anomaly report.
#
# Prerequisites:
#   - Java 11+ on PATH (for Clojure)
#   - Clojure CLI (clj / clojure) on PATH
#   - Elle checkout or deps.edn that pulls elle as a dependency
#
# Usage:
#   ./scripts/verify_elle.sh <history.edn> [--consistency-models snapshot-isolation]
#   ./scripts/verify_elle.sh results/histories/*.edn --output-dir results/elle/
#   ./scripts/verify_elle.sh --help
# -----------------------------------------------------------------------

set -euo pipefail

# ---- Constants ----

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"

# Default Elle deps.edn for running the checker.
# Users can override via ELLE_DEPS_EDN env var or --elle-dir flag.
ELLE_DEPS_EDN="${ELLE_DEPS_EDN:-}"
ELLE_DIR="${ELLE_DIR:-}"

# Default consistency model to check against
DEFAULT_MODEL="snapshot-isolation"

# ---- Usage ----

usage() {
    cat <<'USAGE'
Usage: verify_elle.sh [OPTIONS] <history.edn> [history2.edn ...]

Runs IsoTest .edn history files through the Elle checker.

Options:
  --elle-dir DIR          Path to Elle checkout (must contain deps.edn)
  --consistency-models M  Comma-separated models (default: snapshot-isolation)
                          Options: serializable, snapshot-isolation,
                          read-committed, read-uncommitted, repeatable-read
  --output-dir DIR        Write per-file anomaly reports here (default: alongside input)
  --verbose               Print detailed Elle output
  --dry-run               Show what would be run without executing
  -h, --help              Show this help

Environment:
  ELLE_DIR                Path to Elle checkout (alternative to --elle-dir)
  ELLE_DEPS_EDN           Path to a deps.edn with Elle dependency
  JAVA_HOME               Java installation (needs 11+)

Examples:
  # Check a single history
  ./scripts/verify_elle.sh results/histories/bank_overdraft.edn

  # Check all histories against serializable
  ./scripts/verify_elle.sh results/histories/*.edn \
      --consistency-models serializable --output-dir results/elle/

  # Dry run to verify setup
  ./scripts/verify_elle.sh --dry-run results/histories/test.edn
USAGE
    exit 0
}

# ---- Argument parsing ----

EDN_FILES=()
CONSISTENCY_MODELS="$DEFAULT_MODEL"
OUTPUT_DIR=""
VERBOSE=false
DRY_RUN=false

while [[ $# -gt 0 ]]; do
    case "$1" in
        --elle-dir)
            ELLE_DIR="$2"; shift 2 ;;
        --consistency-models)
            CONSISTENCY_MODELS="$2"; shift 2 ;;
        --output-dir)
            OUTPUT_DIR="$2"; shift 2 ;;
        --verbose)
            VERBOSE=true; shift ;;
        --dry-run)
            DRY_RUN=true; shift ;;
        -h|--help)
            usage ;;
        -*)
            echo "Unknown option: $1" >&2; exit 1 ;;
        *)
            EDN_FILES+=("$1"); shift ;;
    esac
done

if [[ ${#EDN_FILES[@]} -eq 0 ]]; then
    echo "Error: No .edn history files specified." >&2
    echo "Run with --help for usage." >&2
    exit 1
fi

# ---- Dependency checks ----

check_java() {
    if ! command -v java &>/dev/null; then
        echo "Error: java not found on PATH. Elle requires Java 11+." >&2
        echo "Install via: brew install openjdk@11  (macOS)" >&2
        echo "             apt install openjdk-11-jre (Debian/Ubuntu)" >&2
        exit 1
    fi
    # Check version >= 11
    local version
    version=$(java -version 2>&1 | head -1 | sed -E 's/.*"([0-9]+).*/\1/')
    if [[ "$version" -lt 11 ]]; then
        echo "Error: Java $version found, but Elle requires Java 11+." >&2
        exit 1
    fi
}

check_clojure() {
    if ! command -v clj &>/dev/null && ! command -v clojure &>/dev/null; then
        echo "Error: Clojure CLI (clj) not found on PATH." >&2
        echo "Install via: brew install clojure/tools/clojure  (macOS)" >&2
        echo "             See https://clojure.org/guides/install  (Linux)" >&2
        exit 1
    fi
}

resolve_elle_dir() {
    # If ELLE_DIR is set and contains deps.edn, use it
    if [[ -n "$ELLE_DIR" && -f "$ELLE_DIR/deps.edn" ]]; then
        return
    fi

    # If ELLE_DEPS_EDN is set, extract dir
    if [[ -n "$ELLE_DEPS_EDN" && -f "$ELLE_DEPS_EDN" ]]; then
        ELLE_DIR="$(dirname "$ELLE_DEPS_EDN")"
        return
    fi

    # Check if there's a local elle-deps.edn in the project
    if [[ -f "$PROJECT_ROOT/elle-deps.edn" ]]; then
        ELLE_DIR="$PROJECT_ROOT"
        ELLE_DEPS_EDN="$PROJECT_ROOT/elle-deps.edn"
        return
    fi

    # Generate a minimal deps.edn in a temp directory
    local tmp_dir
    tmp_dir="$(mktemp -d)"
    cat > "$tmp_dir/deps.edn" <<'DEPS'
{:deps {elle/elle {:mvn/version "0.2.1"}}}
DEPS
    ELLE_DIR="$tmp_dir"
    echo "Note: Using auto-generated deps.edn at $tmp_dir/deps.edn" >&2
    echo "      Set ELLE_DIR to your Elle checkout for faster repeat runs." >&2
}

# ---- Elle runner ----

# Inline Clojure script that reads an EDN history and runs Elle's checker.
# It accepts the history path and consistency model(s) as arguments.
ELLE_CLJ_SCRIPT='
(require
  (quote [clojure.java.io :as io])
  (quote [clojure.edn :as edn])
  (quote [elle.list-append :as la])
  (quote [elle.rw-register :as rw])
  (quote [jepsen.history :as h]))

(defn parse-history [path]
  (let [reader (java.io.PushbackReader. (io/reader path))
        ops (loop [acc []]
              (let [v (edn/read {:eof ::done} reader)]
                (if (= v ::done)
                  acc
                  (recur (conj acc v)))))]
    ops))

(defn run-check [history-path models]
  (println (str "Checking: " history-path))
  (println (str "Models:   " (pr-str models)))
  (let [history (parse-history history-path)
        _ (println (str "  Loaded " (count history) " operations"))
        ; Try list-append checker first (most common for IsoTest workloads)
        result (try
                 (la/check {:consistency-models models
                            :directory "/tmp/elle-out"} history)
                 (catch Exception e
                   ; Fall back to rw-register if list-append fails
                   (try
                     (rw/check {:consistency-models models
                                :directory "/tmp/elle-out"} history)
                     (catch Exception e2
                       {:valid? :unknown
                        :error (.getMessage e2)}))))]
    (println)
    (println "--- Elle Result ---")
    (println (str "  Valid:     " (:valid? result)))
    (when (:anomaly-types result)
      (println (str "  Anomalies: " (pr-str (:anomaly-types result)))))
    (when (:error result)
      (println (str "  Error:     " (:error result))))
    (println "-------------------")
    (println)
    result))

(let [args *command-line-args*
      history-path (first args)
      model-strs (rest args)
      models (set (map keyword model-strs))]
  (when (empty? history-path)
    (println "Usage: <script> <history.edn> [model1 model2 ...]")
    (System/exit 1))
  (let [result (run-check history-path models)]
    (System/exit (if (= (:valid? result) true) 0 1))))
'

run_elle_check() {
    local edn_file="$1"
    local models="$2"
    local report_file="$3"

    # Convert comma-separated models to space-separated args
    local model_args
    model_args=$(echo "$models" | tr ',' ' ')

    local clj_cmd="clj"
    if command -v clj &>/dev/null; then
        clj_cmd="clj"
    else
        clj_cmd="clojure"
    fi

    local cmd
    if [[ -n "$ELLE_DEPS_EDN" && -f "$ELLE_DEPS_EDN" ]]; then
        cmd="$clj_cmd -Sdeps \"$(cat "$ELLE_DEPS_EDN")\" -e '$ELLE_CLJ_SCRIPT' -- \"$edn_file\" $model_args"
    else
        cmd="cd \"$ELLE_DIR\" && $clj_cmd -e '$ELLE_CLJ_SCRIPT' -- \"$edn_file\" $model_args"
    fi

    if [[ "$DRY_RUN" == "true" ]]; then
        echo "[DRY RUN] Would execute:"
        echo "  cd $ELLE_DIR"
        echo "  $clj_cmd -e '<elle-checker-script>' -- $edn_file $model_args"
        echo "  Report -> $report_file"
        return 0
    fi

    echo "Checking: $edn_file"
    echo "  Models: $models"
    echo "  Report: $report_file"

    # Run the checker, capturing output
    local exit_code=0
    (
        cd "$ELLE_DIR"
        $clj_cmd -e "$ELLE_CLJ_SCRIPT" -- "$edn_file" $model_args
    ) > "$report_file" 2>&1 || exit_code=$?

    if [[ "$VERBOSE" == "true" ]]; then
        cat "$report_file"
    fi

    if [[ $exit_code -eq 0 ]]; then
        echo "  Result: PASS (no anomalies)"
    else
        echo "  Result: FAIL or UNKNOWN (anomalies detected or checker error)"
        echo "  See $report_file for details."
    fi

    return $exit_code
}

# ---- Main ----

main() {
    echo "========================================"
    echo "IsoTest Elle Verification Pipeline"
    echo "========================================"

    check_java
    check_clojure
    resolve_elle_dir

    echo "  Elle dir:   $ELLE_DIR"
    echo "  Models:     $CONSISTENCY_MODELS"
    echo "  Files:      ${#EDN_FILES[@]}"
    echo "========================================"

    local pass_count=0
    local fail_count=0
    local error_count=0

    for edn_file in "${EDN_FILES[@]}"; do
        if [[ ! -f "$edn_file" ]]; then
            echo "Warning: File not found: $edn_file (skipping)" >&2
            ((error_count++)) || true
            continue
        fi

        # Determine report output path
        local report_file
        if [[ -n "$OUTPUT_DIR" ]]; then
            mkdir -p "$OUTPUT_DIR"
            local base
            base="$(basename "$edn_file" .edn)"
            report_file="$OUTPUT_DIR/${base}_elle_report.txt"
        else
            report_file="${edn_file%.edn}_elle_report.txt"
        fi

        local rc=0
        run_elle_check "$edn_file" "$CONSISTENCY_MODELS" "$report_file" || rc=$?

        if [[ $rc -eq 0 ]]; then
            ((pass_count++)) || true
        else
            ((fail_count++)) || true
        fi

        echo ""
    done

    # Summary
    echo "========================================"
    echo "SUMMARY"
    echo "========================================"
    echo "  Total:    ${#EDN_FILES[@]}"
    echo "  Pass:     $pass_count"
    echo "  Fail:     $fail_count"
    echo "  Errors:   $error_count"
    echo "========================================"

    if [[ $fail_count -gt 0 || $error_count -gt 0 ]]; then
        exit 1
    fi
}

main
